//! Real primary grammar failure receipt, never a fabricated private reason.
use super::*;
use std::path::Path;
struct Source(dm_preprocess::AcquiredSource);
impl dm_preprocess::SourceProvider for Source{
 fn initial_environment(&self)->dm_preprocess::InitialEnvironment{dm_preprocess::InitialEnvironment::OriginalChecker0290}
 fn read(&self,_:&Path)->Result<String,String>{Err("real Original source acquisition required".into())}
 fn acquired_source(&self,_:&Path)->Result<Option<dm_preprocess::AcquiredSource>,String>{Ok(Some(self.0.clone()))}
 fn source_acquisition(&self,_:&Path,text:&dm_preprocess::SourceText)->Option<dm_preprocess::AcquiredSource>{self.0.lease().source_text().same_view(text).then(||self.0.clone())}
}
#[test]fn real_original_fatal_parameter_remains_source_exit_two_and_renders_regular_error(){
 let bytes=include_bytes!("../../../fixtures/unified_checks/fatal_parameter_outcome_exact_bad_parameter/project.dme");let source=Source(dm_preprocess::AcquiredSource::from_original_bytes(bytes.to_vec(),()));let seed=dm_tree::checker_builtins::original_analysis_seed().unwrap();let executor=dm_exec::BuildExecutor::new(1).unwrap();let mut state=dm_tree::frontend::RetainedSemanticTree::new();let host=std::sync::Arc::new(crate::query_db::QueryDb::default())as std::sync::Arc<dyn dm_tree::frontend::SettingExpressionQueries>;let result=dm_tree::frontend::build_for_checker_diagnostics_with_state_checked(Path::new("project.dme"),&source,&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:Some(seed.frontend_seed()),observer:None},None,&executor,Some(&mut state),&host);let errors=match result{Err(dm_tree::frontend::FrontendBuildFailure::Diagnostics(errors))=>errors,Err(dm_tree::frontend::FrontendBuildFailure::Operational(actual))=>panic!("real native source test hit operational failure: {actual}"),Ok(_)=>panic!("malformed parameter cannot publish a graph")};assert!(state.snapshot_tree().is_none());let real=errors.iter().find(|error|matches!(error.kind,DiagnosticKind::OriginalFatalParameter{..})).expect("actual native primary parser receipt must be present");assert!(dm_tree::frontend::original_fatal_preparation_outcome(&errors).is_some());assert_eq!(failure_kind([real.kind]),crate::request_failure::FailureKind::Source);assert_eq!(failure_kind([real.kind]).exit_code(),2);
 for kinds in [[DiagnosticKind::UnsupportedModel,real.kind],[real.kind,DiagnosticKind::UnsupportedModel]]{assert_eq!(failure_kind(kinds).exit_code(),2,"a real source error cannot become native fallback")}
 for kinds in [[DiagnosticKind::Internal,real.kind],[real.kind,DiagnosticKind::Internal]]{assert_eq!(failure_kind(kinds),crate::request_failure::FailureKind::Internal);assert_eq!(failure_kind(kinds).exit_code(),70,"a real infrastructure fault still dominates")}
 begin(WarningPolicy::default());let mut output=Vec::new();write_diagnostics(&mut output,std::slice::from_ref(real)).unwrap();let output=String::from_utf8(output).unwrap();assert_eq!(output,"project.dme:1:error: got ')', expected one of: operator, literal, variable, proc call\n");assert!(!output.contains("native unsupported"));assert!(!output.contains("internal compiler error"));assert_eq!(tally().errors,1);assert_eq!(tally().warnings,0);
}

#[test]fn real_original_fatal_declaration_remains_source_error_and_preserves_pinned_comma_outcome(){
 let bytes=include_bytes!("../../../fixtures/unified_checks/fatal_declaration_class_comma/project.dme");let source=Source(dm_preprocess::AcquiredSource::from_original_bytes(bytes.to_vec(),()));let seed=dm_tree::checker_builtins::original_analysis_seed().unwrap();let executor=dm_exec::BuildExecutor::new(1).unwrap();let mut state=dm_tree::frontend::RetainedSemanticTree::new();let host=std::sync::Arc::new(crate::query_db::QueryDb::default())as std::sync::Arc<dyn dm_tree::frontend::SettingExpressionQueries>;let result=dm_tree::frontend::build_for_checker_diagnostics_with_state_checked(Path::new("project.dme"),&source,&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:Some(seed.frontend_seed()),observer:None},None,&executor,Some(&mut state),&host);let errors=match result{Err(dm_tree::frontend::FrontendBuildFailure::Diagnostics(errors))=>errors,Err(dm_tree::frontend::FrontendBuildFailure::Operational(actual))=>panic!("real native source test hit operational failure: {actual}"),Ok(_)=>panic!("actual original class-comma fatal cannot publish a checker graph")};for error in &errors{eprintln!("genuine native fatal declaration: {error:?}")}assert!(state.snapshot_tree().is_none());let real=errors.iter().find(|error|matches!(error.kind,DiagnosticKind::OriginalFatalDeclaration{..})).expect("genuine primary class-comma fatal receipt");let outcome=dm_tree::frontend::original_fatal_preparation_outcome(&errors).expect("actual first fatal original declaration outcome");assert_eq!(outcome.message(),"got ',', expected one of: '/', '[', '=', '(', '{', 'as', 'in', ';', '}'");assert_eq!(outcome.location().1,4);assert_eq!(outcome.location().2,20);assert_eq!(outcome.notes(),["fatal error: the parser cannot continue","constant evaluation will be skipped"]);assert!(!outcome.continues_analysis());assert!(!outcome.compiler_admissible());assert!(real.kind.is_source_error());assert_eq!(failure_kind([real.kind]),crate::request_failure::FailureKind::Source);assert_eq!(failure_kind([real.kind]).exit_code(),2);
 for kinds in [[DiagnosticKind::UnsupportedModel,real.kind],[real.kind,DiagnosticKind::UnsupportedModel]]{assert_eq!(failure_kind(kinds).exit_code(),2)}for kinds in [[DiagnosticKind::Internal,real.kind],[real.kind,DiagnosticKind::Internal]]{assert_eq!(failure_kind(kinds),crate::request_failure::FailureKind::Internal)}
 begin(WarningPolicy::default());let mut output=Vec::new();write_diagnostics(&mut output,std::slice::from_ref(real)).unwrap();let output=String::from_utf8(output).unwrap();assert!(output.contains(":error: got ','"),"{output}");assert!(!output.contains("native unsupported"));assert!(!output.contains("internal compiler error"));assert_eq!(tally().errors,1);assert_eq!(tally().warnings,0);
}

#[test]fn unchecked_original_diagnostic_preparation_fails_closed_before_io_while_ordinary_native_compatibility_stays_unchanged(){
 struct Undemanded;impl dm_preprocess::SourceProvider for Undemanded{fn initial_environment(&self)->dm_preprocess::InitialEnvironment{dm_preprocess::InitialEnvironment::OriginalChecker0290}fn read(&self,_:&Path)->Result<String,String>{panic!("unchecked Original preparation must fail before source read")}fn acquired_source(&self,_:&Path)->Result<Option<dm_preprocess::AcquiredSource>,String>{panic!("unchecked Original preparation must fail before native acquisition")}}
 let executor=dm_exec::BuildExecutor::new(1).unwrap();let mut state=dm_tree::frontend::RetainedSemanticTree::new();let config=dm_tree::frontend::FrontendConfig{workers:1,engine:None,observer:None};
 for stateful in[false,true]{let result=if stateful{dm_tree::frontend::build_for_checker_diagnostics_with_state(Path::new("not-read.dme"),&Undemanded,&Default::default(),config,None,&executor,Some(&mut state))}else{dm_tree::frontend::build_for_checker_diagnostics(Path::new("not-read.dme"),&Undemanded,&Default::default(),config,None,&executor)};let errors=match result{Err(errors)=>errors,Ok(_)=>panic!("unchecked Original must not mint a diagnostic graph")};assert_eq!(errors.len(),1);assert_eq!(errors[0].kind,DiagnosticKind::UnsupportedModel);assert!(errors[0].message.contains("actual checked native resource host"));assert!(dm_tree::frontend::original_fatal_preparation_outcome(&errors).is_none());assert!(state.snapshot_tree().is_none());}
 struct Ordinary;impl dm_preprocess::SourceProvider for Ordinary{fn read(&self,_:&Path)->Result<String,String>{Ok("/datum/ordinary_compatibility\n".into())}}
 let native=dm_tree::frontend::build_for_checker_diagnostics(Path::new("native.dme"),&Ordinary,&Default::default(),config,None,&executor).unwrap();assert!(native.source_view().unwrap().tree().lookup_type(dm_ir::SymbolId::of("/datum/ordinary_compatibility")).is_some());assert_eq!(native.original_analysis_completeness(),None);
}

#[test]fn actual_funded_original_fatal_report_survives_public_error_transport_with_exact_source_kind_message_and_exit(){
 use std::path::Path;let bytes=include_bytes!("../../../fixtures/unified_checks/fatal_parameter_outcome_exact_bad_parameter/project.dme");let source=Source(dm_preprocess::AcquiredSource::from_original_bytes(bytes.to_vec(),()));let seed=dm_tree::checker_builtins::original_analysis_seed().unwrap();let executor=dm_exec::BuildExecutor::new(1).unwrap();let host=std::sync::Arc::new(crate::query_db::QueryDb::default())as std::sync::Arc<dyn dm_tree::frontend::SettingExpressionQueries>;
 let result=dm_tree::frontend::build_for_checker_diagnostics_with_state_checked(Path::new("project.dme"),&source,&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:Some(seed.frontend_seed()),observer:None},None,&executor,None,&host);let mut rows=match result{Err(dm_tree::frontend::FrontendBuildFailure::Diagnostics(rows))=>rows,Err(dm_tree::frontend::FrontendBuildFailure::Operational(error))=>panic!("real source fixture hit an operational failure: {error}"),Ok(_)=>panic!("real malformed source must not issue a frontend")};assert!(rows.is_retained());assert!(rows.legacy_mut().is_none());let actual=dm_tree::frontend::original_fatal_preparation_outcome(&rows).expect("genuine original primary outcome");let expected=actual.message().to_owned();let kind=failure_kind(rows.iter().map(|row|row.kind));assert_eq!(kind,crate::request_failure::FailureKind::Source);
 let error=super::retained_preparation_failure(rows,kind,true,"unreachable missing source message",host.as_ref()).unwrap();let failure=crate::request_failure::RequestFailure::from_error(error.as_ref());assert_eq!(failure.kind,crate::request_failure::FailureKind::Source);assert_eq!(failure.message,expected);assert_eq!(crate::request_failure::exit_code(error.as_ref()),2);assert!(!failure.message.contains("native unsupported"));let wrapped=std::io::Error::new(std::io::ErrorKind::Other,error);assert_eq!(crate::request_failure::classify(&wrapped),crate::request_failure::FailureKind::Source);assert_eq!(crate::request_failure::exit_code(&wrapped),2);
}
